# Surah Al-A'raf (chapter 7) — part 16: ayat 155-164 (IDs 1109-1118)
SURAH = 7

ENTRIES = {
1109: (
"اور موسیٰؑ — نے — اپنی قوم سے — ستر مرد — ہمارے — وعدے کے لیے — منتخب کیے — پس — جب — انہیں — زلزلہ — آ لیا — موسیٰؑ نے کہا — اے میرے رب — اگر تو — چاہتا — تو — انہیں اور مجھے — پہلے — ہلاک کر دیتا — کیا — تو — ہمیں — اس — وجہ سے ہلاک کرے گا — جو — بے وقوف لوگوں نے — ہمارے اندر کیا — یہ — نہیں ہے مگر — تیری آزمائش — تو — اس سے — جسے چاہے — گمراہ کرتا ہے — اور جسے چاہے — ہدایت دیتا ہے — تو — ہمارا — کارساز ہے — پس — ہمیں — بخش دے — اور ہم پر — رحم کر — اور — تو — بہترین بخشنے والے ہیں",
"""۱۔ ستر افراد — زلزلے میں — ہلاک یا بے ہوش۔
۲۔ ’’وَاخْتَارَ مُوسَىٰ قَوْمَهُ سَبْعِينَ رَجُلًا لِّمِيقَاتِنَا فَلَمَّا أَخَذَتْهُمُ الرَّجْفَۃُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّايَ أَتُهْلِكُنَا بِمَا فَعَلَ السُّفَهَاءُ مِنَّا إِنْ هِيَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَاءُ وَتَهْدِي مَن تَشَاءُ أَنتَ وَلِيُّنَا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الْغَافِرِينَ‘‘ — اور موسیٰؑ — نے — اپنی قوم سے — ستر مرد — ہمارے — وعدے کے لیے — منتخب کیے — پس — جب — انہیں — زلزلہ — آ لیا — موسیٰؑ نے کہا — اے میرے رب — اگر تو — چاہتا — تو — انہیں اور مجھے — پہلے — ہلاک کر دیتا — کیا — تو — ہمیں — اس — وجہ سے ہلاک کرے گا — جو — بے وقوف لوگوں نے — ہمارے اندر کیا — یہ — نہیں ہے مگر — تیری آزمائش — تو — اس سے — جسے چاہے — گمراہ کرتا ہے — اور جسے چاہے — ہدایت دیتا ہے — تو — ہمارا — کارساز ہے — پس — ہمیں — بخش دے — اور ہم پر — رحم کر — اور — تو — بہترین بخشنے والے ہیں — یعنی ستر نمائندے — سب زلزلے میں گر پڑے — موسیٰؑ — اللہ سے — بخشش مانگتے ہیں۔
۳۔ عملی سبق: آزمائش — گمراہوں کو — الگ کر کے — حق والوں کو روشن کرتی ہے۔"""
),
1110: (
"اور — ہمارے لیے — اس — دنیا میں — بھلائی — اور آخرت میں بھی — لکھ دے — بے شک — ہم — تیری طرف — لوٹے — اللہ — نے کہا — میں — اپنا عذاب — جسے — چاہوں — اس تک پہنچاؤں — اور — میری رحمت — ہر چیز پر — محیط ہے — تو — عنقریب — میں — اسے — ان لوگوں کے لیے — لکھ دوں گا — جو — تقویٰ اختیار کریں — اور زکوٰۃ دیں — اور — وہ لوگ — جو ہماری آیات پر — ایمان لائیں",
"""۱۔ دنیا و آخرت — دونوں میں فلاح — اللہ کی رحمت کا اظہار۔
۲۔ ’’وَاكْتُبْ لَنَا فِي هَٰذِهِ الدُّنْيَا حَسَنَۃً وَفِي الْآخِرَۃِ إِنَّا هُدْنَا إِلَيْكَ قَالَ عَذَابِي أُصِيبُ بِهِ مَنْ أَشَاءُ وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ الزَّكَاۃَ وَالَّذِينَ هُم بِآيَاتِنَا يُؤْمِنُونَ‘‘ — اور — ہمارے لیے — اس — دنیا میں — بھلائی — اور آخرت میں بھی — لکھ دے — بے شک — ہم — تیری طرف — لوٹے — اللہ — نے کہا — میں — اپنا عذاب — جسے — چاہوں — اس تک پہنچاؤں — اور — میری رحمت — ہر چیز پر — محیط ہے — تو — عنقریب — میں — اسے — ان لوگوں کے لیے — لکھ دوں گا — جو — تقویٰ اختیار کریں — اور زکوٰۃ دیں — اور — وہ لوگ — جو ہماری آیات پر — ایمان لائیں — یعنی اللہ کی رحمت — سب پر محیط ہے — مگر — اس کا خاص حصہ — متقیوں اور زکوٰۃ دینے والوں کے لیے ہے۔
۳۔ عملی سبق: تقویٰ اور زکوٰۃ — اللہ کی رحمت کے دروازے ہیں۔"""
),
1111: (
"وہ لوگ — جو — اس — رسول — نبی — ان پڑھ — کی — پیروی کریں — جسے — وہ — ان کے پاس — تورات اور انجیل — میں — لکھا ہوا — پائیں — وہ — انہیں — بھلائی کا حکم دیتا ہے — اور — برائی سے — روکتا ہے — اور ان — کے لیے — پاکیزہ چیزیں — حلال کرتا ہے — اور — خبیث چیزیں — حرام کرتا ہے — اور — ان — پر — بوجھ — اور — بیڑیاں — جو ان پر تھیں — اتار دیتا ہے — تو جو — اس پر ایمان لائے — اور — اس کی تائید کی — اور — اس کی مدد کی — اور — اس نور — کی — پیروی کی — جو — اس کے ساتھ اتارا گیا — یہی لوگ فلاح پانے والے ہیں",
"""۱۔ آخری نبیؐ — ان پڑھ اور تمام قرآن — سب انجیل و تورات میں — لکھا ہوا۔
۲۔ ’’الَّذِينَ يَتَّبِعُونَ الرَّسُولَ النَّبِيَّ الْأُمِّيَّ الَّذِي يَجِدُونَهُ مَكْتُوبًا عِندَهُمْ فِي التَّوْرَاۃِ وَالْإِنجِيلِ يَأْمُرُهُم بِالْمَعْرُوفِ وَيَنْهَاهُمْ عَنِ الْمُنكَرِ وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَالْأَغْلَالَ الَّتِي كَانَتْ عَلَيْهِمْ فَالَّذِينَ آمَنُوا بِهِ وَعَزَّرُوهُ وَنَصَرُوهُ وَاتَّبَعُوا النُّورَ الَّذِي أُنزِلَ مَعَهُ أُولَٰئِكَ هُمُ الْمُفْلِحُونَ‘‘ — وہ لوگ — جو — اس — رسول — نبی — ان پڑھ — کی — پیروی کریں — جسے — وہ — ان کے پاس — تورات اور انجیل — میں — لکھا ہوا — پائیں — وہ — انہیں — بھلائی کا حکم دیتا ہے — اور — برائی سے — روکتا ہے — اور ان — کے لیے — پاکیزہ چیزیں — حلال کرتا ہے — اور — خبیث چیزیں — حرام کرتا ہے — اور — ان — پر — بوجھ — اور — بیڑیاں — جو ان پر تھیں — اتار دیتا ہے — تو جو — اس پر ایمان لائے — اور — اس کی تائید کی — اور — اس کی مدد کی — اور — اس نور — کی — پیروی کی — جو — اس کے ساتھ اتارا گیا — یہی لوگ فلاح پانے والے ہیں — یعنی آخری نبیؐ — ہر نبی کی دعوت کی تکمیل ہیں — اور ان پر ایمان لانا — نجات کی شرط ہے۔
۳۔ شیعہ تفسیر: آپؐ — ان کتابوں میں — عبدالمطلب کے خاندان کے طور پر — مذکور تھے۔
۴۔ عملی سبق: آخری نبیؐ — کی پیروی — فلاح کی ضمانت ہے۔"""
),
1112: (
"کہدو — اے لوگو — بے شک — میں — تم سب کی طرف — اللہ کا — رسول ہوں — جس — کی — آسمانوں اور زمین میں بادشاہت ہے — اس — کے علاوہ کوئی معبود نہیں — وہی — زندگی دیتا ہے اور — موت دیتا ہے — پس — اللہ پر — اور — اس — کے رسول — نبی — ان پڑھ — پر — ایمان لاؤ — جو — اللہ پر — اور اس کے — کلمات — پر ایمان رکھتا ہے — اور — اس — کی پیروی کرو — شاید — تم ہدایت پا جاؤ",
"""۱۔ تمام انسانوں کے لیے — آخری نبیؐ کی عام رسالت۔
۲۔ ’’قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا الَّذِي لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ لَا إِلَٰهَ إِلَّا هُوَ يُحْيِي وَيُمِيتُ فَآمِنُوا بِاللَّهِ وَرَسُولِهِ النَّبِيِّ الْأُمِّيِّ الَّذِي يُؤْمِنُ بِاللَّهِ وَكَلِمَاتِهِ وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ‘‘ — کہدو — اے لوگو — بے شک — میں — تم سب کی طرف — اللہ کا — رسول ہوں — جس — کی — آسمانوں اور زمین میں بادشاہت ہے — اس — کے علاوہ کوئی معبود نہیں — وہی — زندگی دیتا ہے اور — موت دیتا ہے — پس — اللہ پر — اور — اس — کے رسول — نبی — ان پڑھ — پر — ایمان لاؤ — جو — اللہ پر — اور اس کے — کلمات — پر ایمان رکھتا ہے — اور — اس — کی پیروی کرو — شاید — تم ہدایت پا جاؤ — یعنی نبیؐ کی رسالت — قومی اور علاقائی — نہیں — بلکہ — تمام انسانیت کے لیے — عام ہے۔
۳۔ عملی سبق: آخری نبیؐ — کی پیروی — ہدایت کا راستہ ہے۔"""
),
1113: (
"اور موسیٰؑ کی قوم میں — ایک امت — حق — کی بنیاد پر — ہدایت دیتی ہے — اور — اسی — کے مطابق — انصاف کرتی ہے",
"""۱۔ بنی اسرائیل میں بھی — ایک سچی جماعت باقی رہی۔
۲۔ ’’وَمِن قَوْمِ مُوسَىٰ أُمَّۃٌ يَهْدُونَ بِالْحَقِّ وَبِهِ يَعْدِلُونَ‘‘ — اور موسیٰؑ کی قوم میں — ایک امت — حق — کی بنیاد پر — ہدایت دیتی ہے — اور — اسی — کے مطابق — انصاف کرتی ہے — یعنی بنی اسرائیل کے تمام افراد گمراہ نہیں تھے — ایک گروہ حق پر قائم رہا۔
۳۔ عملی سبق: ہر قوم میں — حق پر — قائم رہنے والے — موجود ہوتے ہیں۔"""
),
1114: (
"اور ہم نے — ان — کو — بارہ — قبائل میں — تقسیم کیا — اور — موسیٰؑ کو — وحی کی — جب — اس کی قوم — نے — اس — سے پانی مانگا — کہ — اپنی چھڑی — پتھر — پر — مارو — تو — اس — سے — بارہ — چشمے — پھوٹ پڑیں گے — ہر — گروہ — نے — اپنا — پانی پینے کا — مقام — معلوم کر لیا — اور — ہم نے — ان پر — بادل کا سایہ کیا — اور — ان پر — من اور سلویٰ اتارا — کھاؤ — ان پاکیزہ چیزوں میں سے — جو ہم نے — تمہیں دی ہیں — اور انہوں نے — ہمارا کچھ نقصان نہیں کیا — بلکہ — وہ — اپنا نقصان کر رہے تھے",
"""۱۔ بارہ قبائل — بارہ چشمے — قرآن کے ایک بہت واضح معجزے۔
۲۔ ’’وَقَطَّعْنَاهُمُ اثْنَتَيْ عَشْرَۃَ أَسْبَاطًا أُمَمًا وَأَوْحَيْنَا إِلَىٰ مُوسَىٰ إِذِ اسْتَسْقَاهُ قَوْمُهُ أَنِ اضْرِب بِّعَصَاكَ الْحَجَرَ فَانفَجَرَتْ مِنْهُ اثْنَتَا عَشْرَۃَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ وَظَلَّلْنَا عَلَيْهِمُ الْغَمَامَ وَأَنزَلْنَا عَلَيْهِمُ الْمَنَّ وَالسَّلْوَىٰ كُلُوا مِن طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ‘‘ — اور ہم نے — ان — کو — بارہ — قبائل میں — تقسیم کیا — اور — موسیٰؑ کو — وحی کی — جب — اس کی قوم — نے — اس — سے پانی مانگا — کہ — اپنی چھڑی — پتھر — پر — مارو — تو — اس — سے — بارہ — چشمے — پھوٹ پڑیں گے — ہر — گروہ — نے — اپنا — پانی پینے کا — مقام — معلوم کر لیا — اور — ہم نے — ان پر — بادل کا سایہ کیا — اور — ان پر — من اور سلویٰ اتارا — کھاؤ — ان پاکیزہ چیزوں میں سے — جو ہم نے — تمہیں دی ہیں — اور انہوں نے — ہمارا کچھ نقصان نہیں کیا — بلکہ — وہ — اپنا نقصان کر رہے تھے — یعنی اللہ — بنی اسرائیل کے لیے — صحرا میں بھی — پانی، ٹھنڈا سایہ اور بہترین کھانا — فراہم کرتا رہا۔
۳۔ عملی سبق: اللہ — بندوں کی ضرورتوں کا خیال رکھتا ہے؛ ناشکری نہ کرو۔"""
),
1115: (
"اور — جب — انہیں کہا گیا — اس — بستی میں — رہو — اور — جہاں سے چاہو — اس سے — کھاؤ — اور — کہو — حطہ (اے ہمارے رب — ہمیں معاف کر) — اور — دروازے سے — سجدہ کرتے ہوئے — داخل ہو — تو — ہم تمہارے گناہ — بخش دیں گے — عنقریب — ہم — نیک عمل کرنے والوں کو — زیادہ دیں گے",
"""۱۔ بیت المقدس — بنی اسرائیل کا داخلہ — توبہ اور سجدہ کے ساتھ۔
۲۔ ’’وَإِذْ قِيلَ لَهُمُ اسْكُنُوا هَٰذِهِ الْقَرْيَۃَ وَكُلُوا مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا حِطَّۃٌ وَادْخُلُوا الْبَابَ سُجَّدًا نَّغْفِرْ لَكُمْ خَطِيئَاتِكُمْ سَنَزِيدُ الْمُحْسِنِينَ‘‘ — اور — جب — انہیں کہا گیا — اس — بستی میں — رہو — اور — جہاں سے چاہو — اس سے — کھاؤ — اور — کہو — حطہ (اے ہمارے رب — ہمیں معاف کر) — اور — دروازے سے — سجدہ کرتے ہوئے — داخل ہو — تو — ہم تمہارے گناہ — بخش دیں گے — عنقریب — ہم — نیک عمل کرنے والوں کو — زیادہ دیں گے — یعنی بیت المقدس میں داخلہ — توبہ اور عاجزی کے ساتھ — ہونا تھا۔
۳۔ عملی سبق: عاجزی اور توبہ — اللہ کی مغفرت کی کلید ہے۔"""
),
1116: (
"پس — جن — لوگوں نے — ان میں سے — ظلم کیا — انہوں نے — اپنا — قول بدل کر — وہ — بنا لیا — جو — انہیں نہیں کہا گیا تھا — تو — ہم — نے — ان پر — آسمان سے — عذاب — بھیجا — اس — ظلم کی وجہ سے — جو — وہ — کرتے تھے",
"""۱۔ بنی اسرائیل — حکم بدل کر — اپنی بدقسمتی — بلا لیتے ہیں۔
۲۔ ’’فَبَدَّلَ الَّذِينَ ظَلَمُوا مِنْهُمْ قَوْلًا غَيْرَ الَّذِي قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًا مِّنَ السَّمَاءِ بِمَا كَانُوا يَظْلِمُونَ‘‘ — پس — جن — لوگوں نے — ان میں سے — ظلم کیا — انہوں نے — اپنا — قول بدل کر — وہ — بنا لیا — جو — انہیں نہیں کہا گیا تھا — تو — ہم — نے — ان پر — آسمان سے — عذاب — بھیجا — اس — ظلم کی وجہ سے — جو — وہ — کرتے تھے — یعنی حکمِ الٰہی کو — بدل کر — اپنی نحوست — خود — بنا لی۔
۳۔ عملی سبق: اللہ کے حکم کی — تبدیلی — نجات کے بجائے — ہلاکت — لاتی ہے۔"""
),
1117: (
"اور — ان سے — اس — بستی کے بارے میں — جو — سمندر کے کنارے — تھی — پوچھو — جب وہ — ہفتے کے دن — حد سے تجاوز کرتے تھے — جب — مچھلیاں — ان — کے پاس — ہفتے کے دن — پانی کی سطح پر — آتی تھیں — اور — جس دن — وہ — ہفتے کا دن نہ مناتے — ان کے پاس نہ آتیں — اسی طرح — ہم — انہیں — ان کے فاسق ہونے کی وجہ سے — آزمائش میں ڈالتے تھے",
"""۱۔ مچھلیوں کی آزمائش — بنی اسرائیل کا سب سے مشہور فتنہ۔
۲۔ ’’وَاسْأَلْهُمْ عَنِ الْقَرْيَۃِ الَّتِي كَانَتْ حَاضِرَۃَ الْبَحْرِ إِذْ يَعْدُونَ فِي السَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ لَا تَأْتِيهِمْ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا يَفْسُقُونَ‘‘ — اور — ان سے — اس — بستی کے بارے میں — جو — سمندر کے کنارے — تھی — پوچھو — جب وہ — ہفتے کے دن — حد سے تجاوز کرتے تھے — جب — مچھلیاں — ان — کے پاس — ہفتے کے دن — پانی کی سطح پر — آتی تھیں — اور — جس دن — وہ — ہفتے کا دن نہ مناتے — ان کے پاس نہ آتیں — اسی طرح — ہم — انہیں — ان کے فاسق ہونے کی وجہ سے — آزمائش میں ڈالتے تھے — یعنی اللہ — حد پار کرنے والوں کو — مچھلیوں کے ذریعے — آزمائش میں ڈالتا ہے — تاکہ وہ — اپنے رویے پر — غور کریں۔
۳۔ عملی سبق: اللہ کی حدوں سے تجاوز — بڑی آزمائش کی طرف لے جاتا ہے۔"""
),
1118: (
"اور — جب — ان میں سے — ایک گروہ — نے — کہا — تم — ایک ایسی قوم کو — کیوں نصیحت کر رہے ہو — جسے — اللہ — ہلاک کرنے والا ہے — یا — اس — کو — سخت عذاب دینے والا ہے — انہوں نے کہا — تمہارے رب کے سامنے — عذر — پیش کرنے کے لیے — اور — شاید — وہ — بچ جائیں",
"""۱۔ بنی اسرائیل — نصیحت کرنے والوں کو — خاموش کرنا چاہتے ہیں۔
۲۔ ’’وَإِذْ قَالَتْ أُمَّۃٌ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا اللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًا شَدِيدًا قَالُوا مَعْذِرَۃً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ‘‘ — اور — جب — ان میں سے — ایک گروہ — نے — کہا — تم — ایک ایسی قوم کو — کیوں نصیحت کر رہے ہو — جسے — اللہ — ہلاک کرنے والا ہے — یا — اس — کو — سخت عذاب دینے والا ہے — انہوں نے کہا — تمہارے رب کے سامنے — عذر — پیش کرنے کے لیے — اور — شاید — وہ — بچ جائیں — یعنی نصیحت کرنے والے — اپنی ذمہ داری — صرف اس لیے ادا کرتے ہیں کہ وہ — اللہ کے سامنے — جواب دہ ہوں گے۔
۳۔ عملی سبق: نصیحت — نتیجہ کی امید پر نہیں — بلکہ — ذمہ داری کی وجہ سے — کرو۔"""
),
}
